package cn.sixnine.filmlog;

import android.app.*;
import android.content.Context;
import android.os.Bundle;
import android.graphics.Color;
import android.text.*;
import android.view.*;
import android.widget.*;
import org.json.*;
import java.io.*;
import java.nio.charset.StandardCharsets;
import java.util.*;
import java.util.function.Consumer;

/** Read-only constants recovered from the original ARM32 snapshot's typed master arrays. */
final class OriginalCatalog {
    private static JSONObject data;
    private static synchronized JSONObject data(Context context){if(data==null)try(InputStream input=context.getAssets().open("pellica-catalog.json");ByteArrayOutputStream bytes=new ByteArrayOutputStream()){byte[] buffer=new byte[8192];int count;while((count=input.read(buffer))!=-1)bytes.write(buffer,0,count);JSONObject value=new JSONObject(new String(bytes.toByteArray(),StandardCharsets.UTF_8));if(value.getJSONArray("films").length()!=518||value.getJSONArray("cameras").length()!=676)throw new IOException("目录不完整");data=value;}catch(Exception error){throw new IllegalStateException("无法读取内置目录",error);}return data;}
    static ArrayList<FilmStockStore.Stock> films(Context context){ArrayList<FilmStockStore.Stock> result=new ArrayList<>();try{JSONArray rows=data(context).getJSONArray("films");for(int i=0;i<rows.length();i++){JSONObject row=rows.getJSONObject(i);FilmStockStore.Stock stock=new FilmStockStore.Stock();stock.id="original:"+row.getString("id");stock.name=row.getString("name");stock.brand=row.getString("brand");stock.iso=row.getInt("iso");stock.process=row.getJSONObject("process").getString("label");ArrayList<String> formats=new ArrayList<>();JSONArray choices=row.getJSONArray("formats");for(int j=0;j<choices.length();j++)formats.add(choices.getJSONObject(j).getString("label"));stock.formats=String.join(",",formats);stock.power="";stock.builtin=true;result.add(stock);}}catch(JSONException error){throw new IllegalStateException("内置片种目录无效",error);}return result;}
    static boolean blackAndWhite(Context context,String name){String key=name.trim().toLowerCase(Locale.ROOT);try{JSONArray rows=data(context).getJSONArray("films");for(int i=0;i<rows.length();i++){JSONObject row=rows.getJSONObject(i);if(row.getString("name").toLowerCase(Locale.ROOT).equals(key)){String process=row.getJSONObject("process").getString("key");return process.equals("bw")||process.equals("bwC41");}}}catch(JSONException error){throw new IllegalStateException("内置片种目录无效",error);}for(FilmStockStore.Stock stock:FilmStockStore.builtins(context))if(stock.id.startsWith("filmer:")&&stock.title().toLowerCase(Locale.ROOT).equals(key))return stock.category.startsWith("BW_");for(String part:new String[]{"hp5","tri-x","trix","delta","fp4","tmax","t-max","pan f","acros","xp2","neopan"})if(key.contains(part))return true;return false;}
    static final class Camera {String name,format,group;boolean matches(String selected){String value=selected==null?"":selected.replace(" ","").toLowerCase(Locale.ROOT);if(value.isEmpty())return true;if(value.equals("35mm"))return format.equals("format35mm");if(value.equals("120"))return format.equals("mediumFormat");if(Arrays.asList("4x5","5x7","8x10","4×5","5×7","8×10").contains(value))return format.equals("largeFormat");return true;}String filmFormat(){return format.equals("format35mm")?"35 mm":format.equals("mediumFormat")?"120":"";}}
    static ArrayList<Camera> cameras(Context context){ArrayList<Camera> result=new ArrayList<>();try{JSONArray rows=data(context).getJSONArray("cameras");for(int i=0;i<rows.length();i++){JSONObject row=rows.getJSONObject(i);Camera camera=new Camera();camera.name=row.getString("name");camera.format=row.getJSONObject("format").getString("key");camera.group=row.getString("group");result.add(camera);}}catch(JSONException error){throw new IllegalStateException("内置机型目录无效",error);}return result;}
    static void chooseCamera(Activity activity,String format,Bundle draft,Consumer<Camera> selected){LinearLayout body=new LinearLayout(activity);body.setOrientation(1);EditText search=new EditText(activity);search.setSingleLine(true);search.setText(draft.getString("cameraCatalogQuery",""));search.setHint("搜索相机型号…");search.setTextColor(0xfff4eee2);search.setHintTextColor(0xffb4a99f);body.addView(search);ListView list=new ListView(activity);body.addView(list,new LinearLayout.LayoutParams(-1,Math.round(340*activity.getResources().getDisplayMetrics().density)));ArrayList<Camera> all=cameras(activity),shown=new ArrayList<>();ArrayAdapter<String> adapter=new ArrayAdapter<>(activity,android.R.layout.simple_list_item_1,new ArrayList<String>());list.setAdapter(adapter);Runnable update=()->{shown.clear();adapter.clear();String term=search.getText().toString().trim().toLowerCase(Locale.ROOT);for(Camera camera:all)if(camera.matches(format)&&(camera.name+" "+camera.group).toLowerCase(Locale.ROOT).contains(term)){shown.add(camera);adapter.add(camera.name+" · "+camera.group);}adapter.notifyDataSetChanged();};search.addTextChangedListener(new TextWatcher(){public void beforeTextChanged(CharSequence s,int a,int b,int c){}public void onTextChanged(CharSequence s,int a,int b,int c){draft.putString("cameraCatalogQuery",s.toString());update.run();}public void afterTextChanged(Editable e){}});AlertDialog dialog=new AlertDialog.Builder(activity).setTitle("选择相机型号").setView(body).setNegativeButton("取消",null).create();list.setOnItemClickListener((parent,view,index,id)->{selected.accept(shown.get(index));dialog.dismiss();});dialog.setOnDismissListener(d->draft.putBoolean("cameraCatalogOpen",false));draft.putBoolean("cameraCatalogOpen",true);update.run();dialog.show();if(dialog.getWindow()!=null)dialog.getWindow().setSoftInputMode(WindowManager.LayoutParams.SOFT_INPUT_STATE_ALWAYS_HIDDEN);}
}
